WITH RecentOrderItems AS (SELECT *, CAST(unit_price AS INT) AS unit_price_int FROM order_items WHERE order_id = 2), order_items_stats AS (SELECT CASE WHEN unit_price_int >= 87 THEN 'high' WHEN unit_price_int >= 21 THEN 'mid' ELSE 'low' END AS unit_price_int_bucket, product_id, COUNT(DISTINCT quantity) AS unique_orders, COUNT(*) AS row_count FROM RecentOrderItems GROUP BY CASE WHEN unit_price_int >= 87 THEN 'high' WHEN unit_price_int >= 21 THEN 'mid' ELSE 'low' END, product_id) SELECT * FROM order_items_stats;
